const body = $json.body;
const docType = body.doc_type || 'GENERAL';
const docDate = new Date().toISOString().split('T')[0].replace(/-/g,'');
const seq = Math.floor(Math.random() * 9000) + 1000;
const docCode = `${docType.substring(0,3).toUpperCase()}-${docDate}-${seq}`;
return [{json: {...body, doc_code: docCode, received_at: new Date().toISOString()}}];

